import { VoyagerRequestType } from "./voyager"
import { WebsiteName } from "./websites"
import { Cookies } from "webextension-polyfill"

export const PB_MESSAGE_FROM_APP_EVENT_NAME = "PB_APP_MESSAGE"

export type IPBUserInfo =
	| {
			id: string
			email: string
	  }
	| undefined

export interface IUserInfo {
	firstName: string
	lastName: string
	headline?: string
	imageUrl?: string
	subscriptionTitles: string[]
	profileId: string
	profileUrl: string
}

interface IFetchCookieUserInfoAppMessage {
	type: "FETCH_COOKIE_USER_INFO"
	payload: {
		cookieName: string
		website: WebsiteName
		value: string
		pbUser: IPBUserInfo
	}
}

interface IFetchCookiesAppMessage {
	type: "FETCH_COOKIES"
	payload: {
		website: WebsiteName
	}
}

type FromBackgroundRuntimeMessages = {
	restart?: boolean

	cookies?: {
		websiteName: WebsiteName
		cookies: Cookies.Cookie[]
	}

	injectCookies?: {
		prefix: string
	}

	userInfo?: {
		info: IUserInfo | null
		websiteName: WebsiteName
		cookieName: string
	}

	voyagerResponse?: {
		type: VoyagerRequestType
		data: unknown
		error?: string
	}
}

export type UpdateTabMessage = {
	action: "update_tab"
	newUrl: string
}

type FromContentScriptRuntimeMessages = {
	action?: UpdateTabMessage["action"]
	newUrl?: UpdateTabMessage["newUrl"]

	getCookies?: {
		websiteName: WebsiteName
	}

	newTab?: {
		websiteName: WebsiteName
		url: string
	}

	notif?: {
		title?: string
		message: string
	}

	restartMe?: boolean

	userInfo?: {
		cookieName: string
		value: string
		website: WebsiteName
		pbUser?: IPBUserInfo
	}

	voyagerRequest?: {
		type: VoyagerRequestType
		slug: string
	}
}

type ToFrontendRuntimeMessages =
	| {
			type: "FETCH_COOKIE_USER_INFO_FULFILLED"
			payload: {
				userInfo: IUserInfo | null
				cookieName: string
				websiteName: WebsiteName
			}
	  }
	| {
			type: "FETCH_COOKIES_FULFILLED"
			payload: {
				cookies: Cookies.Cookie[]
				websiteName: WebsiteName
			}
	  }

function isAppMessage(maybeMessage: unknown): maybeMessage is { type: string } {
	return typeof maybeMessage === "object" && maybeMessage !== null && "type" in maybeMessage
}

export function isFetchCookieUserInfoAppMessage(maybeMessage: unknown): maybeMessage is IFetchCookieUserInfoAppMessage {
	return isAppMessage(maybeMessage) && maybeMessage.type === "FETCH_COOKIE_USER_INFO" && "payload" in maybeMessage
}

export function isFetchCookiesAppMessage(maybeMessage: unknown): maybeMessage is IFetchCookiesAppMessage {
	return isAppMessage(maybeMessage) && maybeMessage.type === "FETCH_COOKIES" && "payload" in maybeMessage
}

export type { FromBackgroundRuntimeMessages, FromContentScriptRuntimeMessages, ToFrontendRuntimeMessages }
