import {
	FromBackgroundRuntimeMessages,
	FromContentScriptRuntimeMessages,
	isFetchCookiesAppMessage,
	isFetchCookieUserInfoAppMessage,
	PB_MESSAGE_FROM_APP_EVENT_NAME,
} from "../../shared/messages"
import { Handler } from "./handler"
import { isPhantombusterSite, WebsiteName } from "../../shared/websites"
import { setUser } from "../../shared/sentry"
import { version } from "../../../package.json"

export class Phantombuster extends Handler {
	public detect() {
		return isPhantombusterSite()
	}

	public onMessage = (msg: FromBackgroundRuntimeMessages) => {
		if (msg.userInfo) {
			this._onUserInfoReceived(msg.userInfo)
		} else if (msg.cookies) {
			this._onCookiesReceived(msg.cookies)
		}
	}

	public async run() {
		/*
		// Setting this attribute to indicate to the phantombuster front
		// that the extension is installed.
		*/
		document.body.setAttribute("data-pb-extension", version || "")

		window.addEventListener(PB_MESSAGE_FROM_APP_EVENT_NAME, this._handleAppMessage as EventListener)
	}

	public destroy() {
		window.removeEventListener(PB_MESSAGE_FROM_APP_EVENT_NAME, this._handleAppMessage as EventListener)
	}

	private _requestCookieUserInfoFromBackground = async (
		userInfoRequest: Required<FromContentScriptRuntimeMessages>["userInfo"],
	) => {
		await this.sendMessage({
			userInfo: userInfoRequest,
		})
	}

	private _requestCookiesFromBackground = (websiteName: WebsiteName) => {
		return this.sendMessage({
			getCookies: {
				websiteName,
			},
		})
	}

	// Handle messages sent by the PhantomBuster React app
	private _handleAppMessage = (event: CustomEvent) => {
		if (isFetchCookieUserInfoAppMessage(event.detail)) {
			if (event.detail.payload.pbUser) {
				const { email, id } = event.detail.payload.pbUser
				setUser({ email, id })
			}

			return this._requestCookieUserInfoFromBackground(event.detail.payload)
		}

		if (isFetchCookiesAppMessage(event.detail)) {
			return this._requestCookiesFromBackground(event.detail.payload.website)
		}

		return undefined
	}

	private _onUserInfoReceived = (userInfoMessage: Required<FromBackgroundRuntimeMessages>["userInfo"]) => {
		return this.dispatchMessageToFrontendApp({
			type: "FETCH_COOKIE_USER_INFO_FULFILLED",
			payload: {
				userInfo: userInfoMessage.info,
				cookieName: userInfoMessage.cookieName,
				websiteName: userInfoMessage.websiteName,
			},
		})
	}

	private _onCookiesReceived = (cookiesMessage: Required<FromBackgroundRuntimeMessages>["cookies"]) => {
		return this.dispatchMessageToFrontendApp({
			type: "FETCH_COOKIES_FULFILLED",
			payload: {
				cookies: cookiesMessage.cookies,
				websiteName: cookiesMessage.websiteName,
			},
		})
	}
}
